log_text = '''a1b2c3d|小明|feat: 增加登录接口
e4f5g6h|小红|fix: 修复订单金额计算
i7j8k9l|小明|docs: 更新 README
m0n1o2p|小红|feat: 增加导出功能
q3r4s5t|小明|fix: 修复登录超时'''


def summarize(log_text):
    total = 0
    authors = {}
    types = {}
    fixes = {}
    for line in str(log_text).splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split('|')
        if len(parts) < 3:
            continue
        _, author, message = parts[0], parts[1], '|'.join(parts[2:])
        total += 1
        authors[author] = authors.get(author, 0) + 1
        kind = 'other'
        if ':' in message:
            head = message.split(':', 1)[0].strip().lower()
            if head and ' ' not in head and len(head) <= 10:
                kind = head
        types[kind] = types.get(kind, 0) + 1
        if kind == 'fix':
            fixes[author] = fixes.get(author, 0) + 1
    hotfix_by = [name for name, _ in sorted(fixes.items(), key=lambda kv: (-kv[1], kv[0]))]
    return {'total': total, 'authors': authors, 'types': types, 'hotfix_by': hotfix_by}


print(summarize(log_text))
